(function() {
    'use strict';

    /*
     * Theme contract.
     * Shipped: two curated themes. theme.css mirrors dark.json as the
     * pre-fetch fallback and is regenerated by .github/scripts/sync-theme.js.
     * A theme may declare `base` ('dark' | 'light', applied as data-theme-base
     * for the few CSS rules that need light/dark branching - never key a
     * selector on a theme id) and a `tokens` section applied with no prefix.
     * Planned for drop-in and accessibility themes, in order:
     *  1. MERGE OVER BASE. Apply every theme as a deep merge over dark.json:
     *     a partial theme becomes legal, and a key a theme omits can no longer
     *     inherit what the previous theme left behind (applyColorVariables
     *     never removes what it wrote). Every readCSSVar(name, fallback) in
     *     the app then becomes provably dead.
     *  2. TRACK AND CLEAR the emitted property names before applying the next
     *     set, so a swap leaves no residue and a reset is possible.
     *  3. register(id, urlOrObject) + list(). A dropped file registers a parsed
     *     object with no fetch; built-in presets (high contrast, colour vision)
     *     register as URLs; .theme-toggle becomes a picker, and validateColors
     *     returns a report the picker can show.
     */
    class ThemeLoader {
        constructor() {
            this.currentTheme = 'dark'; // Matches CSS default
            this.themes = new Map();
            // Safely fallback if CAMConfig isn't loaded (e.g., on the root index or docs)
            this.storageKey = window.CAMConfig?.constants?.storageKeys?.theme || 'cam-theme';
            this.initialized = false;

            // Registry of available themes and their paths
            this.themeRegistry = {
                'dark': '/themes/dark.json',
                'light': '/themes/light.json'
            };
        }

        async init(defaultTheme = 'dark') {
            if (this.initialized) return true;

            const savedTheme = localStorage.getItem(this.storageKey) || defaultTheme;

            // The JSON is applied for EVERY theme, including the default
            // Note theme.css is synced from dark.json with an external script.
            document.documentElement.setAttribute('data-theme', savedTheme);
            try {
                await this.applyTheme(savedTheme);
                this.initialized = true;
                return true;
            } catch (error) {
                console.error('Theme initialization failed, falling back to static CSS:', error);
                this.currentTheme = savedTheme;
                return false;
            }
        }

        async applyTheme(themeId) {
            // Check if already loaded in memory
            if (!this.themes.has(themeId)) {

                // If not, check if it can be found
                if (this.themeRegistry[themeId]) {
                    // Lazy load it now
                    await this.loadTheme(themeId, this.themeRegistry[themeId]);
                } else {
                    console.warn(`Theme ${themeId} not found`);
                    return false;
                }
            }

            const theme = this.themes.get(themeId);

            // DOM Updates
            document.documentElement.setAttribute('data-theme', themeId);
            // theme.base ('dark' | 'light') is the only thing CSS may ever
            // branch on for light/dark-specific rules - never the id itself,
            // which becomes arbitrary once themes are drop-in.
            document.documentElement.setAttribute('data-theme-base', theme.base || 'dark');
            this.applyColorVariables(theme.colors, theme.tokens); // Overwrites the static CSS vars

            document.querySelector('meta[name="theme-color"]')?.setAttribute(
                'content',
                theme.colors?.background?.secondary || '#1a1a1a'
            );

            // Persist
            localStorage.setItem(this.storageKey, themeId);
            this.currentTheme = themeId;

            window.dispatchEvent(new CustomEvent('themechange', {
                detail: { themeId, theme }
            }));

            return true;
        }

        async loadTheme(id, url) {
            const response = await fetch(url);
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const themeData = await response.json();
            this.validateColors(id, themeData.colors);
            this.themes.set(id, themeData);
            return themeData;
        }

        /**
         * One validation pass at load. A malformed value fails differently at
         * every consumer - canvas silently ignores an invalid strokeStyle, CSS
         * drops the declaration - so a theme is checked once, here, loudly, and
         * fixed at its source rather than repaired. Hex must be 6-digit: the
         * palette is deliberately opaque (overlapping transparency is
         * unmanageable); the rgba() scrims are the one translucent exception.
         */
        validateColors(themeId, colors, path = '') {
            if (!colors || typeof colors !== 'object') return;
            for (const [key, value] of Object.entries(colors)) {
                const where = path ? `${path}.${key}` : key;
                if (value !== null && typeof value === 'object') {
                    this.validateColors(themeId, value, where);
                } else if (typeof value === 'string' && (/^#[0-9a-f]{8}$/i.test(value) || !CSS.supports('color', value))) {
                    console.error(`[Theme:${themeId}] ${where} "${value}" is not a valid opaque CSS color.`);
                }
            }
        }

        applyColorVariables(colors, tokens = {}) {
            const root = document.documentElement;
            const set = (k, v) => root.style.setProperty(k, v);

            const flatten = (prefix, obj) => {
                Object.entries(obj).forEach(([key, value]) => {
                    const kebabKey = key.replace(/[A-Z]/g, m => "-" + m.toLowerCase());
                    const newPrefix = prefix ? `${prefix}-${kebabKey}` : kebabKey;

                    if (typeof value === 'object' && value !== null) {
                        flatten(newPrefix, value);
                    } else {
                        set(`--${newPrefix}`, value);
                    }
                });
            };

            // Palette groups only.
            if (colors.background) flatten('color-bg', colors.background);
            if (colors.text) flatten('color-text', colors.text);
            if (colors.border) flatten('color-border', colors.border);
            if (colors.accent) flatten('color-accent', colors.accent);
            if (colors.semantic) flatten('color', colors.semantic);
            if (colors.operations) flatten('color-operation', colors.operations);
            if (colors.render2d) flatten('color-render2d', colors.render2d);
            if (colors.render3d) flatten('color-render3d', colors.render3d);
            if (colors.debug) flatten('color-debug', colors.debug);
            if (colors.geometry) flatten('color-geometry', colors.geometry);
            if (colors.primitives) flatten('color-primitive', colors.primitives);
            if (colors.bw) flatten('color-bw', colors.bw);
            if (colors.pipelines) flatten('color-pipeline', colors.pipelines);
            if (colors.interaction) flatten('color-interaction', colors.interaction);

            // Structure/sizing overrides. NO prefix - a theme's tokens.shadow-sm
            // becomes --shadow-sm directly
            if (tokens && typeof tokens === 'object') {
                for (const [key, value] of Object.entries(tokens)) {
                    set(`--${key}`, value);
                }
            }
        }

        async toggleTheme() {
            const newTheme = this.currentTheme === 'dark' ? 'light' : 'dark';
            await this.applyTheme(newTheme);
            return newTheme;
        }
    }

    window.ThemeLoader = new ThemeLoader();

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => window.ThemeLoader.init());
    } else {
        window.ThemeLoader.init();
    }
})();